6	export const { handlers, signIn, signOut, auth } = NextAuth({
7	  providers: [
8	    Google({
9	      clientId: process.env.GOOGLE_CLIENT_ID,
10	      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
11	    }),
12	    Credentials({
13	      name: "Email and password",
14	      credentials: {
15	        email: { label: "Email", type: "email" },
16	        password: { label: "Password", type: "password" },
17	      },
18	      authorize: async (credentials) => {
19	        const email = credentials?.email;
20	        const password = credentials?.password;
21	        if (typeof email !== "string" || typeof password !== "string") return null;
22	
23	        const user = await verifyPassword(email, password);
24	        if (!user) return null;
25	
26	        return { id: user.id, email: user.email, name: user.name };
27	      },
28	    }),
29	  ],
30	  session: { strategy: "jwt" },
31	  pages: {
32	    signIn: "/signin",
33	  },
34	  callbacks: {
35	    async signIn({ user, account }) {
36	      // Provision (or link to) a local user record on first Google sign-in.
37	      if (account?.provider === "google" && user.email) {
38	        await findOrCreateOAuthUser({
39	          email: user.email,
40	          name: user.name ?? user.email,
41	        });
42	      }
43	      return true;
44	    },
45	  },
46	});
