10	  if (!email || !email.includes("@")) {
11	    return NextResponse.json({ error: "Enter a valid email address." }, { status: 400 });
12	  }
13	  if (password.length < 8) {
14	    return NextResponse.json({ error: "Password must be at least 8 characters." }, { status: 400 });
