```ts
import { NextResponse } from "next/server";
import { createUser, getUserByEmail } from "@/lib/users";

export async function POST(req: Request) {
  const body = await req.json().catch(() => null);
  const email = typeof body?.email === "string" ? body.email.trim() : "";
  const password = typeof body?.password === "string" ? body.password : "";
  const name = typeof body?.name === "string" && body.name.trim() ? body.name.trim() : email.split("@")[0];

  if (!email || !email.includes("@")) {
    return NextResponse.json({ error: "Enter a valid email address." }, { status: 400 });
  }
  if (password.length < 8) {
    return NextResponse.json({ error: "Password must be at least 8 characters." }, { status: 400 });
  }
  if (await getUserByEmail(email)) {
    return NextResponse.json({ error: "An account with that email already exists." }, { status: 409 });
  }

  await createUser({ email, name, password });
  return NextResponse.json({ ok: true });
}
```

## 4. Auth library

**NextAuth (Auth.js) v5 beta** — `package.json` pins `"next-auth": "^5.0.0-beta.32"`. Two providers configured: `Credentials` (bcrypt-hashed passwords, custom `authorize`) and `Google` OAuth. Session strategy is JWT. This is a fully custom, hand-wired NextAuth v5 setup — no other auth library (no Clerk, Auth0, Supabase Auth, etc.) is installed, despite the presence of untracked Clerk docs in the repo (see note above).

## 5. Database / storage

**No real database.** Storage is a plain in-memory JavaScript array in `src/lib/users.ts`, pinned to `globalThis.__notelyUsers` to survive Turbopack's multiple module instantiations in dev/prod. No Prisma, Drizzle, Postgres, SQLite, MongoDB, or any persistence layer — data is lost on server restart. Seed data: two hardcoded users (`ada@example.com`, `grace@example.com`, no passwords set). There is no separate schema file; the `User` type in that same file is the only "schema."

