import bcrypt from "bcryptjs";
import { prisma } from "@/lib/prisma";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // True if this account can sign in with a password (credentials form).
  // False for accounts that only ever signed in via Google or a magic link.
  hasPassword: boolean;
};

function toUser(row: {
  id: string;
  email: string | null;
  name: string | null;
  createdAt: Date;
  passwordHash: string | null;
}): User {
  return {
    id: row.id,
    email: row.email ?? "",
    name: row.name ?? row.email ?? "",
    createdAt: row.createdAt.toISOString().slice(0, 10),
    hasPassword: !!row.passwordHash,
  };
}

export async function listUsers(): Promise<User[]> {
  const rows = await prisma.user.findMany({ orderBy: { createdAt: "asc" } });
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = await prisma.user.findUnique({ where: { id } });
  return row ? toUser(row) : undefined;
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const row = await prisma.user.findUnique({ where: { email: email.toLowerCase() } });
  return row ? toUser(row) : undefined;
}

