// Deletes a user and (via schema cascades) their linked accounts.
export async function deleteUser(userId: string): Promise<void> {
  await prisma.user.delete({ where: { id: userId } });
}

// "Sign out of all devices". Sessions here are JWTs (see src/auth.ts), which
// can't be revoked by deleting a row, so instead every JWT is stamped with
// the sessionVersion it was issued with; bumping the counter here makes every
// outstanding token — on every device — fail its next check in the `jwt`
// callback, forcing a fresh sign-in.
export async function bumpSessionVersion(userId: string): Promise<void> {
  await prisma.user.update({
    where: { id: userId },
    data: { sessionVersion: { increment: 1 } },
  });
}

