import bcrypt from "bcryptjs";
import { prisma } from "@/lib/prisma";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // True if this account can sign in with a password (credentials form).
  // False for accounts that only ever signed in via Google or a magic link.
  hasPassword: boolean;
};

function toUser(row: {
  id: string;
  email: string | null;
  name: string | null;
  createdAt: Date;
  passwordHash: string | null;
}): User {
  return {
    id: row.id,
    email: row.email ?? "",
    name: row.name ?? row.email ?? "",
    createdAt: row.createdAt.toISOString().slice(0, 10),
    hasPassword: !!row.passwordHash,
  };
}

export async function listUsers(): Promise<User[]> {
  const rows = await prisma.user.findMany({ orderBy: { createdAt: "asc" } });
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = await prisma.user.findUnique({ where: { id } });
  return row ? toUser(row) : undefined;
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const row = await prisma.user.findUnique({ where: { email: email.toLowerCase() } });
  return row ? toUser(row) : undefined;
}

// Used by the credentials sign-up flow.
export async function createUser({
  email,
  name,
  password,
}: {
  email: string;
  name: string;
  password: string;
}): Promise<User> {
  const normalized = email.toLowerCase();
  if (await getUserByEmail(normalized)) {
    throw new Error("A user with that email already exists");
  }
  const passwordHash = await bcrypt.hash(password, 10);
  const row = await prisma.user.create({
    data: { email: normalized, name, passwordHash },
  });
  return toUser(row);
}

// Used by the credentials sign-in flow. Returns the user only if the password matches.
export async function verifyPassword(
  email: string,
  password: string
): Promise<User | undefined> {
  const row = await prisma.user.findUnique({ where: { email: email.toLowerCase() } });
  if (!row?.passwordHash) return undefined;
  const valid = await bcrypt.compare(password, row.passwordHash);
  return valid ? toUser(row) : undefined;
}

// Used by OAuth providers (e.g. Google): find the existing account by email, or
// provision one on first sign-in. OAuth-only users have no passwordHash, so they
// can't also be logged into via the credentials form until they set one.
export async function findOrCreateOAuthUser({
  email,
  name,
}: {
  email: string;
  name: string;
}): Promise<User> {
  const normalized = email.toLowerCase();
  const existing = await prisma.user.findUnique({ where: { email: normalized } });
  if (existing) return toUser(existing);
  const row = await prisma.user.create({ data: { email: normalized, name } });
  return toUser(row);
}

// Sets a new password for a user. If they already have one, `currentPassword`
// must match it first. If they don't (Google or magic-link-only accounts),
// this simply adds one, letting them start using the credentials form too.
export async function changePassword({
  userId,
  currentPassword,
  newPassword,
}: {
  userId: string;
  currentPassword?: string;
  newPassword: string;
}): Promise<void> {
  const row = await prisma.user.findUnique({ where: { id: userId } });
  if (!row) throw new Error("User not found");

  if (row.passwordHash) {
    if (!currentPassword) throw new Error("Current password is required");
    const valid = await bcrypt.compare(currentPassword, row.passwordHash);
    if (!valid) throw new Error("Current password is incorrect");
  }

  const passwordHash = await bcrypt.hash(newPassword, 10);
  await prisma.user.update({ where: { id: userId }, data: { passwordHash } });
}

// Deletes a user and (via schema cascades) their linked accounts and sessions.
export async function deleteUser(userId: string): Promise<void> {
  await prisma.user.delete({ where: { id: userId } });
}

// Revokes every active session for a user — "sign out of all devices".
// Sessions are stored in the database (see src/auth.ts's "database" session
// strategy), so deleting the rows immediately invalidates every session
// cookie signed against them, on every device, without waiting for expiry.
export async function revokeAllSessions(userId: string): Promise<void> {
  await prisma.session.deleteMany({ where: { userId } });
}

export async function getCurrentUser(): Promise<User | undefined> {
  // Imported lazily to avoid a module cycle: src/auth.ts imports from this file
  // (verifyPassword, findOrCreateOAuthUser) to implement its providers.
  const { auth } = await import("@/auth");
  const session = await auth();
  if (!session?.user?.email) return undefined;
  return getUserByEmail(session.user.email);
}

