import NextAuth from "next-auth";
import Credentials from "next-auth/providers/credentials";
import Google from "next-auth/providers/google";
import Resend from "next-auth/providers/resend";
import { PrismaAdapter } from "@auth/prisma-adapter";
import { prisma } from "@/lib/prisma";
import { verifyPassword } from "@/lib/users";

export const { handlers, signIn, signOut, auth } = NextAuth({
  // Only used by the magic-link (Resend) provider to persist verification
  // tokens, and to look up/create users for it and Google. The Credentials
  // provider talks to Prisma directly via verifyPassword() and never goes
  // through the adapter.
  adapter: PrismaAdapter(prisma),
  providers: [
    Google({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
      // Auth.js refuses to auto-link an OAuth sign-in to an existing user
      // with the same email unless this is set, since normally that would
      // let anyone with control of an OAuth account take over an account
      // that just happens to share its address. Google verifies the email
      // itself, so trusting that match here is safe and matches this app's
      // original behavior (one account per email, regardless of how you
      // sign in to it).
      allowDangerousEmailAccountLinking: true,
    }),
    Resend({
      apiKey: process.env.RESEND_API_KEY,
      from: process.env.EMAIL_FROM,
    }),
    Credentials({
      name: "Email and password",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      authorize: async (credentials) => {
        const email = credentials?.email;
        const password = credentials?.password;
        if (typeof email !== "string" || typeof password !== "string") return null;

        const user = await verifyPassword(email, password);
        if (!user) return null;

        return { id: user.id, email: user.email, name: user.name };
      },
    }),
  ],
  // Credentials sign-in only supports JWT sessions (Auth.js has no adapter
  // record to attach a database session to), so every provider uses JWT here
  // for one consistent story. "Sign out of all devices" is implemented via
  // User.sessionVersion instead of deleting session rows — see the jwt
  // callback below and lib/users.ts's bumpSessionVersion().
  session: { strategy: "jwt" },
  pages: {
    signIn: "/signin",
    verifyRequest: "/signin/check-email",
  },
  callbacks: {
    async jwt({ token, user, trigger }) {
      if (user?.id) {
        // Fresh sign-in: stamp the token with the user's id and the session
        // version it's valid for.
        token.sub = user.id;
        const row = await prisma.user.findUnique({
          where: { id: user.id },
          select: { sessionVersion: true },
        });
        token.sessionVersion = row?.sessionVersion ?? 0;
        return token;
      }

      if (trigger === "signIn" || trigger === "signUp" || !token.sub) {
        return token;
      }

      // Existing token, subsequent request: re-check against the database.
      // If "sign out of all devices" ran since this token was issued, its
      // sessionVersion is stale — drop it so auth() reports no session.
      const row = await prisma.user.findUnique({
        where: { id: token.sub },
        select: { sessionVersion: true },
      });
      if (!row || row.sessionVersion !== token.sessionVersion) {
        return null;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user && typeof token.sub === "string") {
        session.user.id = token.sub;
      }
      return session;
    },
  },
});

