    if (!res.ok) {
      setError(data.error ?? "Couldn't update password.");
      return;
    }

    setCurrentPassword("");
    setNewPassword("");
    setSuccess(true);
  }

  return (
    <section className={sectionClass}>
      <div>
        <h2 className="text-lg font-medium">
          {hasPassword ? "Change password" : "Set a password"}
        </h2>
        <p className="mt-1 text-sm opacity-70">
